-- 100 more slips across the jar, and fuller notes on 57 of the slips already in it
-- (hours, closed days, what to order, when to go). Researched Nov 2026; costs are rough totals
-- for two and pins are approximate. A title that's already in the jar is skipped, and an
-- update only touches a slip whose notes are still the ones we wrote.
WITH new (title, notes, est_cost, setting, area, venue, lat, lng, duration, tags, energy, closed_days, season_from, season_to) AS (VALUES
  -- at home, together
  ('Reverse dinner: dessert first, starter last', 'Dessert arrives first, the starter last. Each of you picks the other''s dessert, and nobody is allowed to ask what''s for dinner.', 800, 'home', '', '', NULL, NULL, 'short', 'foodie,romantic', 'low', '', NULL, NULL),
  ('Paper plane distance contest', 'Fold three planes each, then throw from the same spot in the hall. The loser makes chai for the winner, who picks the next game.', 0, 'home', '', '', NULL, NULL, 'short', 'games,active', 'med', '', NULL, NULL),
  ('Rangoli battle on the living-room floor', 'Rice, flour and colour powder for one hour, with no stencils or tracing. The other has to guess what each design is meant to be.', 400, 'home', '', '', NULL, NULL, 'short', 'creative,cozy', 'low', '', NULL, NULL),
  ('Mehendi on each other''s hands, symbols only', 'Draw only symbols, no names or words. The ink needs an hour to dry, so you both sit still and talk the whole time.', 300, 'home', '', '', NULL, NULL, 'short', 'creative,romantic', 'low', '', NULL, NULL),
  ('Sock-puppet argument-off', 'Pick a silly argument, like whether dosa is a snack or a meal. You can only speak through sock puppets for ten minutes, and the one who gets more laughs picks the movie.', 0, 'home', '', '', NULL, NULL, 'short', 'games,creative', 'low', '', NULL, NULL),
  ('Cardboard spaceship voyage', 'Build a spaceship from delivery boxes, then fly it around the flat. Each planet you land on needs a snack and a made-up rule.', 150, 'home', '', '', NULL, NULL, 'short', 'creative,adventurous', 'high', '', NULL, NULL),
  ('Write five house rules and sign them', 'Make five rules for the flat, like no sad songs before 10pm or the last chapati belongs to the other. Stick them on the fridge and enforce them for a week.', 0, 'home', '', '', NULL, NULL, 'short', 'creative,cozy', 'low', '', NULL, NULL),
  ('Memory palace walk', 'Walk through the flat room by room and tell a shared memory that happened in each one. The other has to add a detail you forgot.', 0, 'home', '', '', NULL, NULL, 'short', 'romantic,cozy', 'low', '', NULL, NULL),
  ('Tiffin swap for tomorrow', 'Pack each other a tiffin for tomorrow''s work or college, with a note tucked in. It has to taste good cold, so no biryani and no surprises.', 600, 'home', '', '', NULL, NULL, 'short', 'foodie,cozy', 'low', '', NULL, NULL),
  ('Hide-and-seek around the flat', 'Thirty-second rounds with the lights off, and the seeker counts with eyes closed. Whoever gets found the most times does the dishes.', 0, 'home', '', '', NULL, NULL, 'short', 'games,active', 'high', '', NULL, NULL),
  ('Fake front page of your week', 'Write a newspaper front page about the last seven days, with a headline, a weather box and an obituary for the tea you finished. Read it aloud in a newsreader voice.', 0, 'home', '', '', NULL, NULL, 'short', 'creative,games', 'low', '', NULL, NULL),
  ('Torch shadow-puppet theatre', 'Lights off and one torch, and the bedroom wall becomes the stage. Each of you performs a three-minute show with only your hands, and the other guesses the story.', 0, 'home', '', '', NULL, NULL, 'short', 'creative,romantic', 'low', '', NULL, NULL),
  ('Spice-jar challenge: three blind picks', 'Each of you grabs three spice jars without looking, then cooks something edible with those three plus oil, salt and onion. Score each other out of ten.', 500, 'home', '', '', NULL, NULL, 'half_day', 'foodie,games', 'med', '', NULL, NULL),
  ('Kite flying on Sankranti', 'Two kites, a spool of manja and a terrace on Makar Sankranti. One flies, one holds the spool, then swap. Til ladoos for the winner.', 400, 'home', '', '', NULL, NULL, 'short', 'outdoors,games,cultural', 'med', '', 1, 1),
  -- apart, each at our own place
