  ('Commentate each other''s evening', 'For half an hour, one of you narrates the other''s ordinary task live on a call, like a cricket commentator. Making tea and folding laundry both count as a match.', 0, 'apart', '', '', NULL, NULL, 'short', 'games,creative', 'low', '', NULL, NULL),
  ('Dueling headlines for one moment', 'Both of you write a headline for the same moment in your day, like ''Local man finds the last samosa''. Read them aloud together and vote for the funnier one.', 0, 'apart', '', '', NULL, NULL, 'short', 'creative,games', 'low', '', NULL, NULL),
