  ('Dhak Bahiri caves trek', 'The base is Jambhivali village near Karjat, reached by bus or shared jeep. The trek is hard with a steep rock patch, so go as a group with a guide. (Check current operators and route.)', 1500, 'day_trip', 'Karjat, Raigad', 'Dhak Bahiri caves, Jambhivali', 18.912, 73.383, 'full_day', 'adventurous,outdoors', 'high', '', 10, 2),
  ('Sudhagad fort and Pali temple', 'Drive or take a bus to Pali, visit the Ballaleshwar temple, then climb up to Sudhagad for the view. Go early in the day for cooler weather. (Check the climb if it has rained.)', 1200, 'day_trip', 'Pali, Raigad', 'Sudhagad fort', 18.537, 73.29, 'full_day', 'cultural,outdoors', 'med', '', NULL, NULL),
  ('Revdanda fort by the sea', 'Drive or take a bus to Revdanda near Alibaug and walk along the fort walls. Check the tide timings before you go, since the shore is best at low tide.', 1800, 'day_trip', 'Alibaug, Raigad', 'Revdanda fort', 18.553, 72.925, 'half_day', 'cultural,chill', 'low', '', NULL, NULL),
  ('Janjira fort by boat from Murud', 'Drive to Murud and take the boat from Rajpuri jetty across to the sea fort. Boats stop in the monsoon, so check the timings first. (Boat hours vary by source.)', 1400, 'day_trip', 'Murud, Raigad', 'Murud Janjira fort', 18.2966, 72.9661, 'full_day', 'cultural,adventurous', 'med', '', 9, 5),
  ('Kashid beach at low tide', 'Drive via Pen to Kashid, about two and a half hours from Mumbai, and walk the rocks at low tide. Pack a picnic since the shacks can be basic. (Check the tide and weekend traffic.)', 1300, 'day_trip', 'Murud, Raigad', 'Kashid beach', 18.44, 72.902, 'full_day', 'chill,romantic', 'low', '', NULL, NULL),
  ('Malang Gad trek from Kalyan', 'Take a train to Kalyan, then a shared rickshaw towards the Malang Gad base village. The climb is steep in parts, so start early. (Check the monsoon and access rules before going.)', 900, 'day_trip', 'Kalyan, Thane', 'Malang Gad', 19.183, 73.224, 'full_day', 'adventurous,outdoors', 'high', '', 10, 2),
  ('Rajmachi fort at sunrise', 'Take a train to Karjat, then a shared jeep to Rajmachi village. Stay in a homestay and walk up to the fort for sunrise. (Check the season and any trekking rules each year.)', 1500, 'day_trip', 'Karjat, Raigad', 'Rajmachi fort', 18.8, 73.406, 'full_day', 'outdoors,cozy', 'med', '', 10, 2),
  ('Hot springs at Vajreshwari', 'Take a bus or taxi to Ganeshpuri and visit the Vajreshwari hot springs near the temple. Bring a change of clothes and go on a weekday to avoid crowds. (Check the bathing rules.)', 600, 'day_trip', 'Ganeshpuri, Palghar', 'Vajreshwari hot springs', 19.488, 73.03, 'half_day', 'cultural,chill', 'low', '', NULL, NULL),
  ('Monsoon drive over Malshej Ghat', 'Waterfalls off every cliff and clouds across the road in July and August. Stop for bhutta and chai at the top. Drive slow, leave early. (Check for landslide closures.)', 3000, 'day_trip', 'Malshej Ghat', 'Malshej Ghat viewpoint', 19.3357, 73.7787, 'full_day', 'outdoors,romantic,adventurous', 'med', '', 7, 9),
  -- weekends away
  ('Goa on a rented scooter', 'Take a Konkan Railway train or fly to Goa, then rent a scooter to ride between beaches and shacks. Eat seafood at the beach shacks and watch the sunset from the cliffs. (Check the 2026 booking rates.)', 14000, 'travel', 'North Goa', 'Panjim and Calangute', 15.4909, 73.8278, 'weekend', 'chill,foodie', 'med', '', 10, 5),
  ('Strawberry weekend in Mahabaleshwar', 'Drive or take a bus to Mahabaleshwar and stay in a hill-view hotel. Visit Venna Lake, Pratapgad fort and the strawberry farms. (Check the season for strawberries.)', 14000, 'travel', 'Mahabaleshwar, Satara', 'Mahabaleshwar hill station', 17.9307, 73.6477, 'weekend', 'cozy,romantic', 'med', '', 12, 3),
  ('Monsoon weekend in Igatpuri', 'Take a train or drive via Kasara ghat to Igatpuri and stay in a cottage near the hills. Walk to the waterfalls and dam views when the rains are on. (Check the falls and road access.)', 12000, 'travel', 'Igatpuri, Nashik', 'Igatpuri hill town', 19.6947, 73.5611, 'weekend', 'outdoors,romantic', 'med', '', 6, 9),
  ('Konkan coast in Dapoli', 'Drive down the Konkan coast to Dapoli and stay at a beach resort. Visit Kelshi beach and try the local Konkani thali. (Check the road and the resort''s season.)', 16000, 'travel', 'Dapoli, Ratnagiri', 'Kelshi beach, Dapoli', 17.758, 73.181, 'weekend', 'chill,foodie', 'low', '', 10, 3),
  ('Scuba diving at Tarkarli', 'Take a bus or drive to Malvan and stay on Tarkarli beach. Book a Discover Scuba session a few days ahead with a PADI-accredited operator. (Check the operator''s safety record and the season each year.)', 18000, 'travel', 'Malvan, Sindhudurg', 'Tarkarli beach', 16.037, 73.464, 'weekend', 'adventurous,outdoors', 'high', '', 10, 5),
  ('Ruins and sunrise in Hampi', 'Fly to Hubli or take a train to Hospet, then an auto to Hampi. Cycle among the ruins at sunrise and watch the boulders at dusk. (Check temple timings.)', 16000, 'travel', 'Hampi, Karnataka', 'Hampi ruins', 15.335, 76.46, 'weekend', 'cultural,adventurous', 'med', '', 10, 2),
  ('Lake Pichola weekend in Udaipur', 'Fly to Udaipur and stay in a lake-view haveli. Take a boat ride on Lake Pichola at sunset and visit the City Palace. (Check the boat ride hours.)', 22000, 'travel', 'Udaipur, Rajasthan', 'Lake Pichola', 24.5854, 73.7125, 'weekend', 'romantic,cultural', 'low', '', 10, 3),
  ('Flower-carpet weekend at Kaas', 'Drive via Satara to the Kaas plateau and book your entry pass online in advance. Go early to beat the crowds and carry water. (Check the 2026 bloom dates and booking.)', 9000, 'travel', 'Satara, Maharashtra', 'Kaas plateau', 17.7215, 73.8247, 'weekend', 'outdoors,romantic', 'med', '', 8, 10),
  ('Coffee estates in Coorg', 'Fly to Mangalore or take a train to Mysore, then drive to Madikeri. Stay on a coffee estate and walk the plantation trails. (Check the homestay bookings.)', 20000, 'travel', 'Coorg, Karnataka', 'Madikeri coffee estates', 12.4244, 75.7382, 'weekend', 'outdoors,chill', 'med', '', 10, 3),
  ('French Quarter weekend in Pondicherry', 'Take a train or fly to Chennai, then drive or take a bus to Pondicherry. Walk the French Quarter and cycle the seafront promenade. (Check the cafe timings.)', 20000, 'travel', 'Pondicherry', 'White Town, Pondicherry', 11.9416, 79.8083, 'weekend', 'cultural,romantic', 'low', '', 10, 3)
)
INSERT INTO activities (title, notes, est_cost, setting, area, venue, lat, lng, duration, tags, energy, added_by, generated, closed_days, season_from, season_to)
SELECT title, notes, est_cost, setting, area, venue, lat, lng, duration, tags, energy, 'joy', 1, closed_days, season_from, season_to
FROM new WHERE NOT EXISTS (SELECT 1 FROM activities a WHERE a.title = new.title);

-- Fuller notes on slips already in the jar.
UPDATE activities SET notes = 'Karaoke nights daily 6PM-1AM per most listings, at the Andheri West branch. Go early on weekdays for easier mic slots. (Check hours.)' WHERE title = 'Karaoke night at Road House Bluez' AND notes = 'Karaoke nights 6PM-1AM; go early on weekdays for easier mic slots. Verify current hours.';
UPDATE activities SET notes = 'Alpine-themed; reserve ahead. Fondue/raclette + tableside cocktails. Save room for the spiced apple strudel. (Check hours.)' WHERE title = 'Dinner at Luna Et Sol' AND notes = 'Alpine-themed; reserve ahead. Fondue/raclette + tableside cocktails.';
UPDATE activities SET notes = 'Modern regional Indian at Kamala Mills. Order the eggs kejriwal and ghee roast chicken seekh. Reserve for weekends. (Check hours; a temporary closure was reported.)' WHERE title = 'Dinner at The Bombay Canteen' AND notes = 'Modern regional Indian at Kamala Mills. Reserve for weekends.';
UPDATE activities SET notes = 'Authentic Malvani seafood; also outlets in Prabhadevi & Andheri. Try the Malvani prawns thali. Hours vary by source, roughly 11AM-11PM, so check.' WHERE title = 'Malvani seafood at Chaitanya' AND notes = 'Authentic Malvani seafood; also outlets in Prabhadevi & Andheri. ~11AM-11PM.';
UPDATE activities SET notes = 'Hop stalls along the seafront and score each dish out of 10. Stalls run roughly 5PM-11PM and get busy on weekends, so arrive around sunset. Prices about ₹15-200 a dish. (Hours vary by stall.)' WHERE title = 'Food critique date — Carter Road hop' AND notes = 'Hop stalls along the seafront and score each dish out of 10. (Details unverified.)';
UPDATE activities SET notes = 'Listed hours ~11AM-5PM, though which days run is unclear. Fees not published, so call to confirm batch & price.' WHERE title = 'Pottery class together' AND notes = 'Open ~11AM-5PM; fees not published — call to confirm batch & price.';
UPDATE activities SET notes = 'Weekend sessions of about 1 hr 15 min (2:15-3:30PM on District); materials included, take your piece home. Check District for dates.' WHERE title = 'Glass painting workshop' AND notes = 'Weekend afternoon sessions; materials included, take your piece home. Check District for dates.';
UPDATE activities SET notes = 'Aram Nagar, Versova. Open ~12PM-10PM, Tuesday to Sunday; closed Mondays. Call ahead to confirm. https://maps.app.goo.gl/Br5xqRySEUkaeXiw5', closed_days = 'mon' WHERE title = 'Cat café' AND notes = 'Aram Nagar, Versova. Opens ~11-12. https://maps.app.goo.gl/Br5xqRySEUkaeXiw5';
UPDATE activities SET notes = 'Entry from ~₹120; PCs, consoles, VR. Listed as open daily from around noon. Check exact address on Maps.' WHERE title = 'Gaming café' AND notes = 'Entry from ~₹120; PCs, consoles, VR. Check exact address on Maps.';
UPDATE activities SET notes = 'Sim racing and immersive VR listed at ~₹599/person; laser tag not confirmed, so check before booking. [[Thane is roughly midway between {a_area} and {b_area}. ]]Pin unverified.' WHERE title = 'Laser tag & VR gaming' AND notes = '~₹599/person. [[Thane is roughly midway between {a_area} and {b_area}. ]]Pin unverified.';
UPDATE activities SET notes = 'On the highway at Navghar[[, right by {b_area}]]. Official listing says open 24x7 with night karting. Check prices & packages.' WHERE title = 'Go-karting' AND notes = 'On the highway at Navghar[[, right by {b_area}]]. Check prices & packages.';
UPDATE activities SET notes = 'Based near Nerul station (Sector 25). Call ahead for a trial ride; price is an estimate. (Batch timings unverified.)' WHERE title = 'Horse riding' AND notes = 'Call ahead for a trial ride; price is an estimate. (Details unverified.)';
UPDATE activities SET notes = 'Coaching-focused range at Chandivali, Powai. Slot timings are on its LyfSkills page. Confirm walk-in / trial slots before going.' WHERE title = 'Shooting range' AND notes = 'Coaching-focused range — confirm walk-in / trial slots before going.';
UPDATE activities SET notes = '11AM-10PM, hourly slots. Entry listed around ₹400 a head (check). Socks mandatory (sold inside).' WHERE title = 'Snow World' AND notes = '11AM-10PM, hourly slots. Socks mandatory (sold inside).';
UPDATE activities SET notes = 'Weekday tickets ~₹1,299/adult (some sources list ₹999 on Tuesdays). ~10:30AM-8PM, though ride hours vary. Just off the Mumbai-Pune expressway[[, easy from {a_area}]].' WHERE title = 'Amusement park day' AND notes = 'Weekday tickets ~₹1,299/adult. ~10:30AM-8PM. Just off the Mumbai-Pune expressway[[, easy from {a_area}]].';
UPDATE activities SET notes = 'Closed Wednesdays. Go before 10AM. Adult entry listed around ₹50 (check). No outside food.' WHERE title = 'Zoo visit' AND notes = 'Closed Wednesdays. Go before 10AM. No outside food.';
UPDATE activities SET notes = 'Closed Mondays. ~₹150/person; shows ~12, 1:30, 3, 4:30 (check the schedule). Book on nehrucentremumbai.in. Arrive 15 min early.' WHERE title = 'Planetarium show' AND notes = 'Closed Mondays. ~₹150/person; shows ~12, 1:30, 3, 4:30. Arrive 15 min early.';
UPDATE activities SET notes = 'Opens ~5PM; arrive 1-2 hrs before sunset. Book ahead on weekends via OpenTable or the hotel. Smart casual dress code. (Check hours.)' WHERE title = 'Mumbai skyline view' AND notes = 'Opens ~5PM; arrive 1-2 hrs before sunset. Book ahead on weekends.';
UPDATE activities SET notes = 'Park open ~9AM-6PM, closed Mondays. Entry roughly ₹85-100 a head (check). Cycle hire ~₹80 for 2 hrs, ₹500 deposit + ID. Go early.[[ Close to {b_area}.]]', closed_days = 'mon' WHERE title = 'Cycling in Sanjay Gandhi National Park' AND notes = '~₹80/hr cycle hire, 2-hr min, ₹500 deposit + ID. Go early.[[ Close to {b_area}.]]';
UPDATE activities SET notes = '~25 km guided ride from Colaba (HP petrol pump), Fri and Sat nights, starting ~10-10:30PM and ending ~5:30AM (check). Official price ~₹650 with cycle, ₹299 bring-your-own (check current dates).' WHERE title = 'Midnight cycling ride' AND notes = '~25 km guided ride, 10:15PM to ~5:30AM, ~₹1,000/person with cycle. Check current dates.';
UPDATE activities SET notes = 'Get there 30-40 min before sunset for a seawall spot. Street food nearby at Chowpatty: gola, kala khatta, pav bhaji, with stalls opening around 5PM.' WHERE title = 'Sunset date at Marine Drive' AND notes = 'Get there 30-40 min before sunset for a seawall spot. Street food nearby.';
UPDATE activities SET notes = '~1.5-2 hrs on the expressway; old highway is prettier. Make a playlist. Tiger''s Point has a sheer 650 m drop and great sunsets, free entry; a small waterfall runs there in monsoon. (Check Lion''s Point hours.)' WHERE title = 'Long drive to Lonavala' AND notes = '~1.5-2 hrs on the expressway; old highway is prettier. Make a playlist.';
UPDATE activities SET notes = 'Ajanta closed Mon, Ellora closed Tue. Ellora first; taxi to Ajanta (~100 km), with a shuttle from the T-point. Entry around Rs 40 for Indians, Rs 600 for foreigners; open about 9 to 5:30. Cost incl. travel + stay. (Check ASI fees.)' WHERE title = 'Ajanta & Ellora caves weekend' AND notes = 'Ajanta closed Mon, Ellora closed Tue. Ellora first; taxi to Ajanta (~100 km). Cost incl. travel + stay.';
UPDATE activities SET notes = 'Book online; shows sell out on weekends. The café is open about 11 AM to 10 PM for a pre-show bite and an Irish coffee. (Check what''s on.)' WHERE title = 'A play at Prithvi Theatre' AND notes = 'Book online; shows sell out on weekends. Irish coffee at Prithvi Café before the show. (Check what''s on.)';
UPDATE activities SET notes = 'Ferry from the Gateway of India (~1 hr each way); first boat around 9 AM, last return around 5:30 PM. Closed Mondays. Entry about Rs 10 for Indians, more for foreigners, plus a camera fee. Go early, carry water. (Check ferry timings.)' WHERE title = 'Ferry to Elephanta Caves' AND notes = 'Ferry from the Gateway of India (~1 hr each way). Closed Mondays. Go early, carry water. (Check ferry timings.)';
UPDATE activities SET notes = 'Thane Creek boats run on high tide, roughly Nov to Apr; go early for photos. Regular boats about Rs 300 to 400 a head plus sanctuary entry. Book the boat in advance. (Check the season and tide.)' WHERE title = 'Flamingo boat ride' AND notes = 'Thane Creek, roughly Nov to May, best near high tide. Book the boat in advance. (Check the season before going.)';
UPDATE activities SET notes = 'Inside Sanjay Gandhi National Park. Closed Mondays, last cave entry around 4:30 PM. Park entry plus shuttle fee at the gate, or the 7 km forest walk. Start early; cabs or cycles from the gate too. (Check timings and fees.)' WHERE title = 'Hike to Kanheri Caves' AND notes = 'Inside Sanjay Gandhi National Park. Start early; cabs or cycles from the gate. Closed Mondays. (Check timings.)';
UPDATE activities SET notes = 'Malpua, kebabs, phirni and rabdi jalebi. Best after dark, and legendary during Ramzan; around 9 PM is quieter. Nearest stations Sandhurst Road or Byculla. Go hungry. (Pin approximate.)' WHERE title = 'Late-night food walk on Mohammed Ali Road' AND notes = 'Malpua, kebabs and phirni. Best after dark, and legendary during Ramzan. Go hungry. (Pin approximate.)';
UPDATE activities SET notes = 'No cars up top: park at Dasturi Naka, then walk, ride a horse or take the toy train from Neral. Toy train runs about four times a day since its late-2025 restart; suspended in heavy monsoon. Entry around Rs 50 a head. Same side as Saltt. (Check the toy train.)' WHERE title = 'Matheran day trip' AND notes = 'No cars up top, just forest trails and viewpoints. Toy train from Neral when it''s running. Same side as Saltt. (Check the toy train.)';
UPDATE activities SET notes = 'A quiet old tank with steps and temples, hidden in Malabar Hill. Go early. Nearest stations Charni Road or Grant Road, then a taxi up. A music festival at the tank is held in January. (Pin approximate.)' WHERE title = 'Banganga Tank and the Walkeshwar lanes' AND notes = 'A quiet old tank with steps and temples, hidden in Malabar Hill. Go early. (Pin approximate.)';
UPDATE activities SET notes = 'Free entry. Usually open from early morning to about 9 PM, though listings differ, so check. Walk the gardens and the old-shoe park next door, then a view over Marine Drive. An overhaul was planned, so check it is open. (Pin approximate.)' WHERE title = 'Morning at the Hanging Gardens' AND notes = 'Walk the gardens and the old-shoe park next door, then a view over Marine Drive. (Pin approximate.)';
UPDATE activities SET notes = 'Free gallery shows, usually open 11 AM to 7 PM and closed Sundays. Then the lanes, cafés and bookshops around Kala Ghoda. (Check what''s showing.)', closed_days = 'sun' WHERE title = 'Jehangir Art Gallery and a Kala Ghoda wander' AND notes = 'Free gallery shows, then the lanes, cafés and bookshops around Kala Ghoda. (Check what''s showing.)';
UPDATE activities SET notes = 'The fish market at full speed at dawn, best from about 5 to 7 AM; wholesale trading is mostly done by the time retail crowds arrive. Wear closed shoes and ask before close-up photos. Breakfast in Colaba after. (Check photography rules.)' WHERE title = 'Sunrise at Sassoon Docks' AND notes = 'The fish market at full speed at dawn. Wear shoes you don''t mind, then breakfast in Colaba. (Check photography rules.)';
UPDATE activities SET notes = 'Forest trail up to the Karnala fort pinnacle, best Oct to Apr for migratory birds. Open roughly 7 AM to 6 PM, so start early. Entry around Rs 35 to 60 a head plus camera fee. Carry water, no refills. (Check timings.)', season_to = 4 WHERE title = 'Karnala Bird Sanctuary hike' AND notes = 'Forest trail up to the Karnala fort pinnacle, best Oct to Feb. Start early, carry water. (Check timings.)';
UPDATE activities SET notes = 'Portuguese-era fort ruins overgrown with trees; entry is free, roughly 9 AM to 6 PM. Best Nov to Feb. Then the beach nearby. (Pin approximate.)' WHERE title = 'Vasai Fort and the beach' AND notes = 'Portuguese-era fort ruins overgrown with trees, then the beach nearby. (Pin approximate.)';
UPDATE activities SET notes = 'Kundalika river, usually June to October when the dam releases water. Minimum age around 14. Book a licensed operator; prices from about Rs 800 a head. (Check the season.)' WHERE title = 'River rafting at Kolad' AND notes = 'Kundalika river, usually monsoon to early winter when the dam releases water. Book an operator. (Check the season.)';
UPDATE activities SET notes = 'Mumbai''s oldest museum, all gold and tiles, inside the Byculla zoo gardens. Closed Wednesdays and some public holidays. Open about 10 AM to 5:30 PM, last ticket around 5 PM. (Check timings.)' WHERE title = 'Dr. Bhau Daji Lad Museum' AND notes = 'Mumbai''s oldest museum, all gold and tiles, inside the Byculla zoo gardens. Usually closed Wednesdays. (Check timings.)';
UPDATE activities SET notes = 'The causeway to the dargah over the sea, only walkable at low tide, so check the tide first. Open roughly 6 AM to 10 PM; Thursdays and Fridays are the busiest. Then a fresh juice at the corner.' WHERE title = 'Walk out to Haji Ali at sunset' AND notes = 'The causeway to the dargah over the sea, then a fresh juice at the corner. Only walkable at low tide, so check the tide.';
UPDATE activities SET notes = 'Walk the 1.4 km promenade as the lights come on, then dinner in Hiranandani. Go before full dark for safety; only chai and bhelpuri carts for snacks. (Pin approximate.)' WHERE title = 'Evening by Powai Lake' AND notes = 'Walk the promenade as the lights come on, then dinner in Hiranandani. (Pin approximate.)';
UPDATE activities SET notes = 'Old Portuguese ramparts over the Sea Link. No entry fee. Closing times are listed inconsistently (around 6:30 to 7:30 PM), so check. Find a spot on the rocks and stay till the lights come on.' WHERE title = 'Sunset at Bandra Fort' AND notes = 'Old Portuguese ramparts over the Sea Link. Find a spot on the rocks and stay till the lights come on.';
UPDATE activities SET notes = 'A five-minute boat across the creek, then the quiet beaches and lanes on the other side. Roughly 6.30 am to 6.30 pm, about ₹5 a head, and monsoon sailings are often cancelled. (Check ferry timings.)' WHERE title = 'Ferry from Versova to Madh Island' AND notes = 'A five-minute boat across the creek, then the quiet beaches and lanes on the other side. (Check ferry timings.)';
UPDATE activities SET notes = '₹500 each to find the strangest thing you can for the other. Most shops open about 11 am to 7.30 pm, and many close on Fridays. (Bargain kindly.)' WHERE title = 'Chor Bazaar treasure hunt' AND notes = '₹500 each to find the strangest thing you can for the other. Many shops close on Fridays. (Bargain kindly.)';
UPDATE activities SET notes = 'A huge golden dome you can sit inside in silence, then the beach. Entry is free (donations welcome). Open daily about 9 am to 7 pm, last entry 6.30 pm. Take the ferry from Borivali. (Check timings.)' WHERE title = 'Global Vipassana Pagoda and Gorai beach' AND notes = 'A huge golden dome you can sit inside in silence, then the beach. Take the ferry from Borivali. (Check timings.)';
UPDATE activities SET notes = 'Old Buddhist caves near Karjat with a waterfall in front during and just after the monsoon, roughly June to September. The trail gets slippery and the final steps are a scramble. (Pin approximate.)' WHERE title = 'Kondana Caves trek' AND notes = 'Old Buddhist caves near Karjat with a waterfall in front during and after the monsoon. Moderate trail. (Pin approximate.)';
UPDATE activities SET notes = 'Wine tours and tastings at the vineyards, a slow lunch, a sunset over the vines. Walk-ins are allowed, but book a tasting ahead, especially on weekends. Roughly 11 am to 7 pm. (Check hours.)' WHERE title = 'Vineyard weekend in Nashik' AND notes = 'Wine tours and tastings at the vineyards, a slow lunch, a sunset over the vines. (Book a tasting.)';
UPDATE activities SET notes = 'For a few weeks before the monsoon, usually mid-May to mid-June, the trees light up with fireflies, most intensely from 8 to 11 pm. Camp by the lake. (Check the season each year.)' WHERE title = 'Fireflies at Bhandardara' AND notes = 'For a few weeks before the monsoon the trees light up with fireflies. Camp by the lake. (Check the season each year.)';
UPDATE activities SET notes = 'Two floors of Japanese-inspired cafe with a glass roof and a floating matcha bar upstairs. Try the Matcha Misu and the mochi. Open daily 8 am to 11.30 pm. (Check hours.)' WHERE title = 'Matcha at Mokai' AND notes = 'Two floors of Japanese-inspired cafe with a glass roof and a floating matcha bar upstairs. Try the Matcha Misu and the mochi. Moved to Pali Hill in 2026. (Check hours.)';
UPDATE activities SET notes = 'The specialty roaster''s flagship in an old Ranwar cottage. Order something you''ve never tried from the brew bar. Open daily, about 7.30 am to 10 pm. (Check hours.)' WHERE title = 'Coffee and bakes at Subko' AND notes = 'The specialty roaster''s flagship in an old Ranwar cottage. Order something you''ve never tried from the brew bar. (Check hours.)';
UPDATE activities SET notes = 'Skylit old-warehouse cafe with its own little gallery, on Ropewalk Lane. Listed open roughly 8.30 am to 11.30 pm. Slow coffee, then a wander through the art district. (Check hours.)' WHERE title = 'Kala Ghoda Cafe' AND notes = 'Skylit old-warehouse cafe with its own little gallery, on Ropewalk Lane. Slow coffee, then a wander through the art district.';
UPDATE activities SET notes = 'The Colaba classic with Mario Miranda''s cartoons all over the walls. Open 8 am to 11.30 pm daily. Find yourselves in the murals over a cold coffee.' WHERE title = 'Cafe Mondegar and the Mario Miranda walls' AND notes = 'The Colaba classic with Mario Miranda''s cartoons all over the walls. Find yourselves in the murals over a cold coffee.';
UPDATE activities SET notes = 'Hyderabad''s much-loved patisserie, now in a tall, airy Colaba space on Pasta Lane: a cafe by day and a bar by evening. Try the mango and coconut choux bun and a slice of cake. About ₹2,000 to ₹2,500 for two. (Check hours.)' WHERE title = 'Conçu in Colaba' AND notes = 'Hyderabad''s much-loved patisserie, now in a tall, airy Colaba space: a cafe by day and a bar by evening. Share a slice of cake. (Price is a guess.)';
UPDATE activities SET notes = 'The open-air theatre cafe under the trees, since the 1970s. Irish coffee and the bun maska, before or after a play. Open daily, roughly 10.30 am to 10.30 pm. (Check hours.)' WHERE title = 'Irish coffee at Prithvi Cafe' AND notes = 'The open-air theatre cafe under the trees, since the 1970s. Irish coffee and the bun maska, before or after a play.';
UPDATE activities SET notes = 'All-day cafe by Juhu beach with a breezy terrace. Go for a lazy breakfast, then walk on the sand. Listed as open about 8 am to 11.30 pm. (Check hours.)' WHERE title = 'Breakfast at Silver Beach Cafe' AND notes = 'All-day cafe by Juhu beach with a breezy terrace. Go for a lazy breakfast, then walk on the sand. (Check hours.)';
UPDATE activities SET notes = 'A Versova cafe with a comic-book library in the basement. Each pick a comic for the other to read over coffee. One directory lists noon to 1 am. (Check hours.)' WHERE title = 'Comics and coffee at Leaping Windows' AND notes = 'A Versova cafe with a comic-book library downstairs. Each pick a comic for the other to read over coffee. (Check hours.)';
UPDATE activities SET notes = 'The London cafe famous for walls of flowers and pink everything, at Jio World Plaza in BKC. Open about 11 am to 10.30 pm, veg and non-veg, no alcohol. Dress for the photos. (Check hours.)' WHERE title = 'Pink tea at EL&N' AND notes = 'The London cafe famous for walls of flowers and pink everything, at Jio World Plaza in BKC. Dress for the photos. (Check hours.)';
UPDATE activities SET notes = 'The Bandra brunch spot people queue for. Go early on a weekend, order two plates and swap halfway. Reported open about 7 am to 11 pm; the menu is all-vegetarian. (Check hours.)' WHERE title = 'Brunch at Boojee Cafe' AND notes = 'The Bandra brunch spot people queue for. Go early on a weekend, order two plates and swap halfway. (Check hours.)';
UPDATE activities SET notes = 'A cosy, European-feeling café with books around. Thick hot chocolate and a long chat. Listed open about 11 am to 11 pm daily. (Price is a guess; check hours.)' WHERE title = 'Hot chocolate at Magari' AND notes = 'A cosy, European-feeling café with books around. Thick hot chocolate and a long chat. (Price is a guess; check hours.)';
